'use strict';
const T=window.KEYBOUND_TOKENS;
const W=[['royal_fantasy','皇家奇幻战争','厚石城防 · 英勇又幽默','ROYAL FRONTIER'],['sci_fi','科幻星港','模块机械 · 环形能量','ORBIT OUTPOST'],['modern','现代工坊','微缩城市 · 灵巧创造','LITTLE WORKSHOP'],['ancient','古文明遗迹','青铜砂岩 · 探索发现','SUNSTONE RUINS'],['fairytale','童话花园','植物魔法 · 轻盈生命','CRYSTAL GARDEN']];
const modes=[['castle','守护键之城','六波城防 · 建塔与施法','◇','策略与稳定输入'],['fighter','指尖训练庭院','陪练格斗 · 输入打断蓄力','✦','反应与连击'],['aliens','星港防卫线','护盾防守 · 完词发射激光','◎','切换与防御'],['rain','流星拦截','拦截下降目标 · 守住90秒','↯','反应与优先级'],['racing','工坊拉力赛','完整输入推进 · 三连击加速','➜','连续与稳定'],['sprint','计时训练站','60秒专注 · 挑战自己的节奏','◷','准确与速度'],['dojo','基准键学堂','无压力 · 先学正确手指','▦','基础指法'],['moles','遗迹寻字','六个洞口 · 看准再敲','⌁','找键与切换'],['balloons','花园气球节','上升气球 · 让文字变成花瓣','♧','找键与反应'],['bubbles','晶露泡泡','自由选目标 · 慢慢输入','◌','准确与自由练习']];
const lessons=window.KEYBOUND_LESSONS;
let preferences={world:'royal_fantasy',lesson:0,reduced:false,sound:true,textScale:1};
try{const saved=JSON.parse(localStorage.getItem('keybound.designV2')||'null');if(saved){for(const k of Object.keys(preferences))if(typeof saved[k]===typeof preferences[k])preferences[k]=saved[k]}}catch{}
if(!W.some(w=>w[0]===preferences.world))preferences.world='royal_fantasy';
if(!Number.isInteger(preferences.lesson)||preferences.lesson<0||preferences.lesson>=lessons.length)preferences.lesson=0;
if(![1,1.25,1.5].includes(preferences.textScale))preferences.textScale=1;
const state={...preferences,page:'hall',purpose:'training',all:false,mode:'castle',build:true,pad:0,towers:[null,null,null,null],gold:240,hp:75,level:0,word:'',typed:0,hits:0,errors:0,target:0,modal:null,origin:'games',guidePreview:'f'};
const main=document.querySelector('#main'),overlay=document.querySelector('#overlay');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,action,primary=false,attrs='')=>`<button ${primary?'class="primary"':''} data-action="${action}" ${attrs}>${label}</button>`;
const world=()=>W.find(w=>w[0]===state.world), lesson=()=>lessons[state.lesson];
const board=html=>`<div class="board"><div class="paper">${html}</div></div>`;
const keycaps=value=>`<span class="lesson-keys">${[...value.slice(0,8)].map(x=>`<span class="keycap">${esc(x.toUpperCase())}</span>`).join('')}</span>`;
function save(){try{localStorage.setItem('keybound.designV2',JSON.stringify({world:state.world,lesson:state.lesson,reduced:state.reduced,sound:state.sound,textScale:state.textScale}))}catch{}}
function skin(){document.body.dataset.world=state.world;document.body.dataset.page=state.page;const p=T.themes[state.world].palette;for(const [k,v]of Object.entries(p))document.documentElement.style.setProperty('--'+k,v);document.documentElement.style.setProperty('--world-pos',W.findIndex(w=>w[0]===state.world)*25+'%');document.documentElement.style.setProperty('--scale',state.textScale);document.body.classList.toggle('reduced',state.reduced)}
function announce(text){document.querySelector('#announcement').innerHTML=`<div class="toast">${esc(text)}</div>`;clearTimeout(announce.timer);announce.timer=setTimeout(()=>document.querySelector('#announcement').replaceChildren(),2600)}
function worldSwitch(){return `<div class="world-switch" role="group" aria-label="切换世界皮肤">${W.map(w=>`<button data-world="${w[0]}" aria-pressed="${state.world===w[0]}">${w[1]}</button>`).join('')}</div>`}
function head(title,subtitle,extra=''){return `<div class="page-head"><div><div class="eyebrow">${world()[3]} / ${state.purpose==='challenge'?'CHALLENGE':'LEARN & ADVENTURE'}</div><h1>${title}</h1><p>${subtitle}</p></div>${extra}</div>`}
function tile(m){return `<article class="game-tile"><div class="tile-head"><span class="mode-icon" aria-hidden="true">${m[3]}</span><div><h3>${m[1]}</h3><div class="mini">${m[2]}</div></div></div><div class="badge-row"><span class="tag">${m[4]}</span><span class="tag">${['dojo','bubbles'].includes(m[0])?'无时间压力':state.purpose==='training'?'训练节奏':'挑战规则'}</span></div><p class="small-caption">带入：${esc(lesson().name)}<br>${esc(lesson().hint)}</p>${btn(state.purpose==='challenge'?'开始挑战':'用本课练习','intro:'+m[0],false,`aria-label="${m[1]}，${state.purpose==='challenge'?'开始挑战':'用本课练习'}"`)}</article>`}
function selectedModes(){return modes.filter(m=>(state.all||T.mode_worlds[m[0]]===state.world)&&(state.purpose!=='challenge'||!['dojo','bubbles'].includes(m[0])))}
function hall(){return head('小小手指，探索大大世界。','选一个喜欢的世界，把每一次练习变成冒险。')+`<div class="board"><div class="continue"><div><div class="eyebrow">CONTINUE LEARNING / 从自己的节奏开始</div><h2>${esc(lesson().name)} ${keycaps(lesson().keys)}</h2><p>${esc(lesson().description)}</p></div>${btn('继续本课 <kbd>Enter</kbd>','continue',true,'data-initial')}</div></div><div class="section-head"><h2>五个世界，同一场成长</h2><p>每个世界 2 款玩法 · 课程可自由搭配</p></div><div class="worlds">${W.map((w,i)=>`<button class="world-card" data-world="${w[0]}" aria-pressed="${state.world===w[0]}"><span class="world-art" style="--pos:${i*25}%" aria-hidden="true"></span><span class="world-meta"><strong>${w[1]}</strong><small>${w[2]}</small></span></button>`).join('')}</div><div class="section-head"><h2>${world()[1]} · 去玩一局</h2>${btn('查看全部十款游戏','allgames')}</div><div class="game-grid">${modes.filter(m=>T.mode_worlds[m[0]]===state.world).map(tile).join('')}</div>`}
function coursePage(){return head('从定位键，到指尖冒险。','先练准确与回位，再把同一课带进喜欢的小游戏。',btn('查看正确手指摆放 <kbd>F1</kbd>','guide'))+`<div class="flow-note"><span class="tag">01 基础找键</span>→<span class="tag">02 双手组合</span>→<span class="tag">03 真实单词</span>→<span class="tag">04 符号与句子</span></div><div class="split"><div class="lessons-grid">${lessons.map((l,i)=>`<button class="lesson" data-lesson="${i}" aria-pressed="${state.lesson===i}" ${state.lesson===i?'data-initial':''}><span class="number">${String(i+1).padStart(2,'0')}</span><span class="description"><strong>${esc(l.name.split('·').at(-1).trim())}</strong><small>${esc(l.description)}</small></span><span class="state">${state.lesson===i?'◆ 当前':'开放'}</span></button>`).join('')}</div><aside>${board(`<div class="eyebrow muted">CURRENT LESSON</div><h2>${esc(lesson().name)}</h2>${keycaps(lesson().keys)}<p style="margin-top:20px">${esc(lesson().hint)}</p><div class="inset" style="margin:24px 0"><strong>先找准，再提速</strong><p class="small-caption muted">手指击键后回到基准行。训练内容保持一致，只改变玩法。</p></div>${btn('选择小游戏 →','continue',true)}`)}</aside></div>`}
function gamesPage(challenge=false){return head(challenge?'准备好，挑战自己。':'这节课，你想怎么玩？',`${challenge?'挑战成绩单独记录':'训练内容保持一致，只改变玩法'} · ${esc(lesson().name)}`,btn('更换课程/词库','courses'))+worldSwitch()+`<div class="toolbar" style="margin-bottom:24px">${btn(state.all?'◆ 全部十款':'本世界玩法','toggleAll',false,`aria-pressed="${state.all}"`)}<span class="light-muted">${challenge?'计时、反应与策略压力；无压力玩法在训练中体验。':esc(lesson().hint)}</span></div><div class="game-grid">${selectedModes().map(tile).join('')}</div>`}
function getFinger(char){const shifts='~!@#$%^&*()_+{}|:"<>?',bases='`1234567890-=[]\\;\',./';let base=char.toLowerCase();const at=shifts.indexOf(char);if(at>=0)base=bases[at];if(char===' ')return{base:' ',finger:8,label:'拇指 · 空格',shift:false};const groups=['`1qaz','2wsx','3edc','45rtfgvb','67yuhjnm','8ik,','9ol.','0p;/-=[]\\\''];const finger=groups.findIndex(g=>g.includes(base));return{base,finger,label:['左手小指','左手无名指','左手中指','左手食指','右手食指','右手中指','右手无名指','右手小指'][finger]||'查看键盘',shift:at>=0||(/[A-Z]/.test(char))}}
function keyboard(char){const info=getFinger(char);return `<div class="keyboard" aria-label="QWERTY键盘，下个键${esc(char)}">${['1234567890','qwertyuiop','asdfghjkl;','zxcvbnm,./'].map(row=>`<div class="row">${[...row].map(c=>`<span class="keycap ${info.base===c?'active':''} ${'fj'.includes(c)?'home':''}">${esc(c.toUpperCase())}</span>`).join('')}</div>`).join('')}<div class="row"><span class="keycap ${info.shift&&info.finger>=4?'active':''}">Shift</span><span class="keycap space ${char===' '?'active':''}">SPACE</span><span class="keycap ${info.shift&&info.finger<4?'active':''}">Shift</span></div></div>`}
function hands(char){const f=getFinger(char);return `<div class="hands" aria-hidden="true">${[0,1].map(side=>`<div class="hand">${[0,1,2,3].map(i=>`<span class="finger ${f.finger===(side?7-i:i)?'active':''}"></span>`).join('')}<span class="thumb ${f.finger===8?'active':''}"></span></div>`).join('')}</div>`}
function coach(char='f',full=false){const f=getFinger(char);return `<h3>指法教练</h3><div class="coach-key">${char===' '?'␣':esc(char)}</div><p style="text-align:center"><strong>${esc(f.label)}</strong></p>${hands(char)}${keyboard(char)}<p class="coach-compact">${f.shift?'对侧小指按住 Shift，再击主键。':'左手 A S D F · 右手 J K L ;'}<br>F / J 凸点定位，击键后回到基准行。</p>${full?'<p class="small-caption muted" style="margin-top:18px">教学示意图，不会检测真实手势。</p>':btn('展开指法 <kbd>F1</kbd>','guide')}`}
function buildControls(){return `<div class="build-panel"><h3>防线指挥所</h3><div class="resource">金币 <span id="gold">${state.gold}</span> G · 城防 ${state.hp}/100</div><p class="small-caption muted">${state.build?'准备 · 1–4选基座':'战斗 · 字母只用于打字'}<br>基座 ${state.pad+1} · ${state.towers[state.pad]||'空闲'}</p>${state.build?`<div class="build-row"><button data-action="tower:fire"><kbd>Q</kbd> 火塔<small>60 G</small></button><button data-action="tower:ice"><kbd>W</kbd> 冰塔<small>70 G</small></button><button data-action="tower:storm"><kbd>E</kbd> 雷塔<small>85 G</small></button></div><div class="build-row two">${btn('<kbd>U</kbd> 升级<br>50 G','upgrade')}${btn('<kbd>R</kbd> 修复<br>35 G','repair')}</div><div class="build-row"><button data-action="reinforce:power"><kbd>A</kbd> 火力<small>65 G</small></button><button data-action="reinforce:chain"><kbd>S</kbd> 连锁<small>65 G</small></button><button data-action="reinforce:walls"><kbd>D</kbd> 城防<small>65 G</small></button></div>${btn('开始第1波 <kbd>N</kbd>','wave',true)}`:`<div class="inset"><strong>本波情报</strong><p class="small-caption muted">疾行兽：优先拦截<br>盾卫：需要连续命中<br>统领：输入打断蓄力</p></div>${btn('展开指法 <kbd>F1</kbd>','guide')}${btn('查看演示结算','result')}`}<p class="small-caption muted">建筑与资源为交互示意。</p></div>`}
function wordHTML(){const w=state.word,at=state.typed;return `<span class="typed">${esc(w.slice(0,at))}</span><span class="current">${esc(w[at]||'')}</span>${esc(w.slice(at+1))}`}
function game(){const m=modes.find(m=>m[0]===state.mode),isCastle=state.mode==='castle';const stage=isCastle?`<div class="stage ${state.world}" aria-label="城堡布局示意，四个可选建设基座"><div class="castle" aria-hidden="true"></div>${[0,1,2,3].map((i)=>`<button class="pad p${i+1} ${state.pad===i?'selected':''}" data-pad="${i}" ${state.pad===i&&state.build?'data-initial':''} ${state.build?'':'disabled'} aria-label="基座${i+1}，${state.towers[i]||'空闲'}"><span class="tower">${state.towers[i]?{'火焰塔':'♨','寒冰塔':'❄','雷电塔':'↯'}[state.towers[i]]:'+'}</span><small>${i+1}</small></button>`).join('')}${!state.build?`<div class="threat t1 selected" id="scene-target">${esc(state.word)}<small>疾行兽 · 优先拦截</small></div><div class="threat t2">${esc(lesson().words[1]||'j')}<small>铁盾卫 · 生命 2/2</small></div><div class="threat t3">${esc(lesson().words[0])}<small>统领 · 输入打断</small></div>`:''}<div class="stage-note">${state.build?'选基座 → 建造元素塔 → N 开始下一波':'词牌始终高于特效 · Tab切换目标 · 完整输入施法'}</div></div>`:`<div class="demo-battle"><div class="world-portrait" aria-hidden="true"></div><div class="target-card"><div class="eyebrow muted">${m[4]}</div><div class="target-word" id="scene-target">${wordHTML()}</div><p class="muted" style="margin-top:20px">${m[2]}</p><span class="tag" style="margin-top:16px">交互示例 · 非完整关卡</span></div></div>`;
return head(m[1],`${state.purpose==='challenge'?'挑战':'训练'} / ${esc(lesson().name)} · ${world()[1]}`,`<div class="toolbar">${btn('音效 '+(state.sound?'开':'关')+' <kbd>F2</kbd>','sound')}${btn('暂停 <kbd>Esc</kbd>','pause')}</div>`)+`<div class="game-shell">${stage}<aside class="board"><div class="paper">${isCastle?buildControls():coach(state.word[state.typed]||'f')}</div></aside></div><div class="target-strip"><div><div class="eyebrow muted">${state.build&&isCastle?'BUILD / 选择你的防线':'NEXT KEY / 专注下一个字符'}</div><div class="target-word" id="typed-target">${state.build&&isCastle?'1  2  3  4':wordHTML()}</div></div><div class="small-caption muted" id="input-status">演示命中 ${state.hits} · 错误 ${state.errors}<br>${state.build&&isCastle?'建设快捷键仅在准备阶段启用':'Backspace 撤回 · F1 指法 · F2 音效'}</div>${!isCastle?btn('查看结算示例','result'):''}</div>`}
function profile(){return head('看见每一次进步。','学习记录与挑战成绩分开呈现，世界更换不改变课程进度。')+`<div class="stat-grid"><div class="stat"><span>课程进阶</span><strong>01 / 10</strong><small>原型示例，非真实掌握记录</small></div><div class="stat"><span>训练准确率</span><strong>96%</strong><small>示例数据</small></div><div class="stat"><span>值得再练的键</span><strong>F / J</strong><small>先保持准确，再追求速度</small></div></div><div class="split" style="margin-top:24px">${board(`<h2>下一次，让双手更熟悉一点。</h2><p class="muted" style="margin:16px 0 24px">回到定位键，练习击键后回位。学习档案应提供可执行的下一步。</p>${btn('继续本课','continue',true,'data-initial')}`)}${board(`<h3>存档与设备</h3><p class="small-caption muted" style="margin:16px 0">正式游戏设计：本机/浏览器自动保存，提供JSON备份。当前原型仅保存界面偏好。</p>${btn('查看存档设计','storage')}`)}</div>`}
function components(){return head('同一套交互，五种世界外壳。','换材质与装饰，保留功能语义、焦点与按压手感。')+worldSwitch()+board(`<div class="split"><div><h2>${world()[1]} · 主按钮状态</h2><div class="status-grid"><div class="status-sample">${btn('开始训练','sample',true)}<small>默认 / Default</small></div><div class="status-sample"><button class="primary pressed-sample" data-action="sample">开始训练</button><small>按下 / Pressed</small></div><div class="status-sample">${btn('开始训练','sample',true,'data-initial')}<small>聚焦 / Focus → Tab查看</small></div><div class="status-sample">${btn('◆ 当前课程','sample',false,'aria-pressed="true"')}<small>选中 / Selected</small></div><div class="status-sample">${btn('资源不足 · 差20 G','sample',false,'disabled')}<small>禁用 / Disabled</small></div><div class="status-sample">${btn('◌ 正在保存','sample',false,'disabled aria-busy="true"')}<small>加载 / Loading</small></div></div><div class="section-head"><h3>稳定的功能语义</h3></div><div class="badge-row"><span class="tag">✓ 正确</span><span class="tag">× 错误</span><span class="tag">△ 危险</span><span class="tag">◆ 选中</span></div><p class="small-caption muted" style="margin-top:18px">图标与文字冗余表达，不依赖红绿色。文字留在原生控件中。</p></div><div><div class="hero-preview" aria-label="${world()[1]}概念样张"></div><p class="small-caption muted" style="margin-top:16px">五世界概念样张，不是精灵图集。战场示意用于结构与词牌测试。</p>${btn('查看奖励弹窗','result')}</div></div>`)}
function render(focus=true){const oldFocus=focusID(document.activeElement);skin();main.innerHTML=({hall,lessons:coursePage,games:()=>gamesPage(false),challenges:()=>gamesPage(true),game,profile,components}[state.page])();document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-current',b.dataset.page===state.page?'page':'false'));document.querySelector('#context-note').textContent=state.page==='game'?'F1 指法 · F2 音效 · Esc 暂停':world()[1]+' / 课程与玩法自由搭配';if(focus)requestAnimationFrame(()=>{(main.querySelector('[data-initial]')||main.querySelector('button'))?.focus({preventScroll:true})});else if(oldFocus)requestAnimationFrame(()=>main.querySelector(oldFocus)?.focus({preventScroll:true}))}
const history=[];
function navigate(page,purpose=null){if(state.page===page&&purpose===null)return;if(state.page==='game'&&page!=='game'&&!state.modal){showModal('leave');return}history.push({page:state.page,focus:focusID(document.activeElement),scroll:window.scrollY,purpose:state.purpose});if(purpose)state.purpose=purpose;else if(page==='lessons'||page==='games'||page==='hall')state.purpose='training';state.page=page;render();window.scrollTo(0,0)}
function focusID(el){return el?.dataset.action?'[data-action="'+el.dataset.action+'"]':el?.dataset.world?'[data-world="'+el.dataset.world+'"]':el?.dataset.lesson?'[data-lesson="'+el.dataset.lesson+'"]':el?.dataset.page?'[data-page="'+el.dataset.page+'"]':null}
function back(){if(state.modal){closeModal();return}if(state.page==='game'){showModal('pause');return}const old=history.pop();if(old){state.page=old.page;state.purpose=old.purpose;render(false);requestAnimationFrame(()=>{(old.focus&&document.querySelector(old.focus)||main.querySelector('button'))?.focus({preventScroll:true});window.scrollTo(0,old.scroll)})}else if(state.page!=='hall'){state.page='hall';render()}else announce('你已在世界大厅。Tab或方向键可以选择入口。')}
let modalFocus=null,modalStack=[];
function showModal(kind){clearTimeout(announce.timer);document.querySelector('#announcement').replaceChildren();if(state.modal&&state.modal!==kind)modalStack.push(state.modal);if(!state.modal)modalFocus=document.activeElement;state.modal=kind;document.querySelector('.app').inert=true;let body='',title='';
if(kind==='intro'){const m=modes.find(m=>m[0]===state.mode);title=m[1];body=`<p>${esc(lesson().name)} · ${esc(lesson().hint)}</p><div class="inset" style="margin:20px 0"><h3>输入 → ${state.mode==='castle'?'发射魔法，保护要塞':m[4]}</h3><p>${m[2]}。${state.purpose==='training'?'先保持准确，再提高速度。':'本次使用挑战节奏，结果独立记录。'}</p></div><p class="small-caption">本页为交互原型：可体验选择、键入、建塔与结算，战斗数据仅作示意。</p><div class="actions">${btn('返回选择','close')}${btn('开始本局','start',true,'data-modal-initial')}</div>`}
if(kind==='guide'){title='先摆好手，再继续冒险。';body=`<div class="split" style="grid-template-columns:1fr 1fr"><div id="guide-live">${coach(state.guidePreview,true)}</div><div><h3>找到 F / J 的凸点</h3><p style="margin-top:18px">左手：A S D F<br>右手：J K L ;<br>拇指轻放空格键。</p><p style="margin-top:18px">手腕放松，击键后回到基准行。大写与上档符号使用对侧Shift。</p><p class="small-caption" style="margin-top:18px">按实体键盘可查看指法分工。教学图不检测真实手势。</p></div></div><div class="actions">${btn('摆好了，返回 <kbd>Esc</kbd>','close',true,'data-modal-initial')}</div>`}
if(kind==='pause'){title='休息一下，冒险等你回来。';body=`<p>游戏输入已暂停，当前演示进度保留。双手回到F/J定位键后继续。</p><div class="actions">${btn('结束本局','leave')}${btn('指法图示','guide')}${btn('继续 <kbd>Esc</kbd>','close',true,'data-modal-initial')}</div>`}
if(kind==='leave'){title='结束这次练习？';body=`<p>本局尚未结算。返回集合后可重新选择玩法；已有正式游戏存档不受本原型影响。</p><div class="actions">${btn('返回游戏集合','leave-confirm')}${btn('继续练习','close',true,'data-modal-initial')}</div>`}
if(kind==='result'){title='每一次练习，都在让双手更熟悉。';body=`<p>结算样式示例 · 以下数据不写入学习档案</p><div class="stat-grid" style="margin-top:22px"><div class="stat">准确率<strong>96%</strong><small>保持稳稳的节奏</small></div><div class="stat">有效WPM<strong>18.4</strong><small>示例速度</small></div><div class="stat">最高连击<strong>12</strong><small>示例连击</small></div></div><div class="inset" style="margin-top:22px">下一次试试：F / J击键后回位，先准后快。</div><div class="actions">${btn('返回游戏集合','leave-confirm')}${btn('再练一次','restart',true,'data-modal-initial')}</div>`}
if(kind==='settings'){title='让冒险更适合你。';body=`<div class="setting-row"><span>音效<small>视觉反馈始终可用；此原型不播放游戏音频</small></span>${btn(state.sound?'开':'关','sound')}</div><div class="setting-row"><span>减少动态<small>关闭过渡、弹跳与抖动</small></span>${btn(state.reduced?'开':'关','reduced')}</div><div class="setting-row"><span>文字大小<small>正文随设置放大，页面允许滚动</small></span>${btn(Math.round(state.textScale*100)+'%','textscale')}</div><div class="actions">${btn('完成，返回','close',true,'data-modal-initial')}</div>`}
if(kind==='storage'){title='存档状态也要让人安心。';body=`<p>正式游戏设计：本机或浏览器自动保存学习进度，支持导入、导出JSON备份。保存失败时保留现有记录并说明原因。</p><div class="inset" style="margin-top:20px">原型仅保存世界、课程与显示偏好，不读取正式Godot存档，也不执行进度替换。</div><div class="actions">${btn('知道了','close',true,'data-modal-initial')}</div>`}
overlay.innerHTML=`<div class="modal-shade"><section class="modal board" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="paper"><div class="eyebrow muted">KEYBOUND / ${world()[3]}</div><h2 id="dialog-title">${title}</h2>${body}</div></section></div>`;overlay.querySelector('[data-modal-initial]')?.focus()}
function closeModal(restore=true){const prior=restore?modalStack.pop():null;if(!restore)modalStack=[];state.modal=null;overlay.replaceChildren();document.querySelector('.app').inert=false;if(prior){showModal(prior);return}if(restore)(modalFocus?.isConnected?modalFocus:main.querySelector('button'))?.focus()}
function start(){closeModal(false);state.origin=state.page;state.page='game';state.build=state.mode==='castle';state.gold=240;state.hp=75;state.pad=0;state.towers=[null,null,null,null];state.hits=0;state.errors=0;state.typed=0;state.target=0;state.word=lesson().words[0];state.guidePreview=state.word[0];render();if(!state.build)requestAnimationFrame(()=>main.focus({preventScroll:true}));window.scrollTo(0,0)}
function build(kind){if(state.page!=='game'||state.mode!=='castle'||!state.build)return;const names={fire:'火焰塔',ice:'寒冰塔',storm:'雷电塔'},cost={fire:60,ice:70,storm:85}[kind];if(state.towers[state.pad]){announce('这个基座已有防御塔。按U升级，或1–4选择其他基座。');return}if(state.gold<cost){announce('金币不足，还差'+(cost-state.gold)+' G。');return}state.gold-=cost;state.towers[state.pad]=names[kind];render(false);announce(names[kind]+'已建造，基座'+(state.pad+1))}
function action(a){if(a.startsWith('reinforce:')){state.reinforceType=a.split(':')[1];a='reinforce'}if(a.startsWith('intro:')){state.mode=a.split(':')[1];state.world=T.mode_worlds[state.mode];skin();showModal('intro');return}if(a.startsWith('tower:')){build(a.split(':')[1]);return}switch(a){case'continue':navigate('games','training');break;case'courses':navigate('lessons',state.purpose);break;case'allgames':state.all=true;navigate('games','training');break;case'toggleAll':state.all=!state.all;render();break;case'start':case'restart':start();break;case'close':closeModal();break;case'settings':case'pause':case'leave':case'result':case'storage':showModal(a);break;case'guide':state.guidePreview=state.page==='game'?(state.word[state.typed]||'f'):'f';showModal('guide');break;case'leave-confirm':closeModal(false);state.page=state.purpose==='challenge'?'challenges':'games';render();break;case'sound':state.sound=!state.sound;save();if(state.modal==='settings')showModal('settings');else if(state.page==='game')render(false);announce('音效'+(state.sound?'开启':'关闭')+'（界面状态示例）');break;case'reduced':state.reduced=!state.reduced;save();skin();showModal('settings');break;case'textscale':state.textScale=[1,1.25,1.5][([1,1.25,1.5].indexOf(state.textScale)+1)%3];save();render(false);showModal('settings');break;case'wave':if(!state.build)return;state.build=false;render();requestAnimationFrame(()=>main.focus({preventScroll:true}));announce('战斗开始，字母键现在只用于输入。');break;case'upgrade':if(!state.towers[state.pad]){announce('请先建造防御塔。');return}if(state.gold<50){announce('升级需要50 G。');return}state.gold-=50;state.level++;render(false);announce('防御塔升级。');break;case'reinforce':if(state.gold<65){announce('强化需要65 G。');return}state.gold-=65;render(false);announce('城堡强化完成（示意）。');break;case'repair':if(state.hp===100){announce('城防已满，无需修复。');return}if(state.gold<35){announce('修复需要35 G。');return}state.gold-=35;state.hp=Math.min(100,state.hp+35);render(false);announce('城防已修复至'+state.hp+'。');break;case'sample':announce('组件反馈示例：按压、聚焦与选择使用不同状态。');break}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.action)action(b.dataset.action);else if(b.dataset.page)navigate(b.dataset.page,b.dataset.page==='challenges'?'challenge':null);else if(b.dataset.world){state.world=b.dataset.world;state.all=false;save();render(false);requestAnimationFrame(()=>document.querySelector(`button[data-world="${state.world}"]`)?.focus({preventScroll:true}))}else if(b.dataset.lesson!==undefined){state.lesson=Number(b.dataset.lesson);save();render(false);requestAnimationFrame(()=>document.querySelector(`[data-lesson="${state.lesson}"]`)?.focus({preventScroll:true}))}else if(b.dataset.pad!==undefined){state.pad=Number(b.dataset.pad);render(false);requestAnimationFrame(()=>document.querySelector(`[data-pad="${state.pad}"]`)?.focus({preventScroll:true}))}});
function focusables(root=document){return [...root.querySelectorAll('button:not([disabled]),[tabindex="0"]')].filter(e=>e.getClientRects().length&&getComputedStyle(e).visibility!=='hidden'&&!e.closest('[inert]'))}
function arrowFocus(key){const scope=state.modal?overlay:document.querySelector('.app'),list=focusables(scope),current=document.activeElement;if(!list.includes(current)){list[0]?.focus();return}const r=current.getBoundingClientRect(),cx=r.x+r.width/2,cy=r.y+r.height/2;const horizontal=['ArrowLeft','ArrowRight'].includes(key),positive=['ArrowRight','ArrowDown'].includes(key);let candidates=list.filter(x=>x!==current).map(el=>{const z=el.getBoundingClientRect(),dx=z.x+z.width/2-cx,dy=z.y+z.height/2-cy,along=horizontal?dx:dy,cross=horizontal?dy:dx;return{el,along,cross}}).filter(x=>positive?x.along>8:x.along< -8).sort((a,b)=>(Math.abs(a.along)+Math.abs(a.cross)*3)-(Math.abs(b.along)+Math.abs(b.cross)*3));candidates[0]?.el.focus();candidates[0]?.el.scrollIntoView({block:'nearest',inline:'nearest'})}
function typeChar(c){if(c===state.word[state.typed]){state.typed++;if(state.typed===state.word.length){state.hits++;state.target++;state.typed=0;state.word=lesson().words[state.target%lesson().words.length];announce('✓ 输入完成 · '+state.hits+'次命中')}state.guidePreview=state.word[state.typed];updateTyping()}else{state.errors++;announce('× 试试下一个键：'+(state.word[state.typed]===' '?'空格':state.word[state.typed]));updateTyping()}}
function updateTyping(){document.querySelector('#typed-target').innerHTML=wordHTML();const target=document.querySelector('#scene-target');if(target)target.innerHTML=wordHTML()+(state.mode==='castle'?'<small>疾行兽 · 优先拦截</small>':'');document.querySelector('#input-status').innerHTML=`演示命中 ${state.hits} · 错误 ${state.errors}<br>Backspace 撤回 · F1 指法 · F2 音效`;if(state.mode!=='castle')document.querySelector('.game-shell aside .paper').innerHTML=coach(state.word[state.typed]||'f')}
document.addEventListener('keydown',e=>{if(e.isComposing||e.ctrlKey||e.altKey||e.metaKey||e.repeat)return;if(e.key==='Escape'){e.preventDefault();back();return}if(e.key==='F1'){e.preventDefault();if(state.modal==='guide')closeModal();else action('guide');return}if(e.key==='F2'&&state.page==='game'&&!state.modal){e.preventDefault();action('sound');return}if(state.modal){if(e.key==='Tab'){const list=focusables(overlay),at=list.indexOf(document.activeElement);e.preventDefault();list[(at+(e.shiftKey?-1:1)+list.length)%list.length]?.focus();return}if(state.modal==='guide'&&e.key.length===1&&e.key!==' '){e.preventDefault();state.guidePreview=e.key;document.querySelector('#guide-live').innerHTML=coach(e.key,true);return}if(e.key.startsWith('Arrow')){e.preventDefault();arrowFocus(e.key)}return}if(state.page==='game'){if(state.mode==='castle'&&state.build){const k=e.key.toLowerCase(),map={q:'tower:fire',w:'tower:ice',e:'tower:storm',u:'upgrade',a:'reinforce:power',s:'reinforce:chain',d:'reinforce:walls',r:'repair',n:'wave'};if('1234'.includes(k)&&k.length===1){state.pad=Number(k)-1;render(false);e.preventDefault();return}if(map[k]){e.preventDefault();action(map[k]);return}}else{if(e.key==='Tab'){e.preventDefault();state.typed=0;state.target++;state.word=lesson().words[state.target%lesson().words.length];updateTyping();return}if(e.key==='Backspace'){e.preventDefault();state.typed=Math.max(0,state.typed-1);updateTyping();return}if(e.key.length===1){e.preventDefault();typeChar(e.key);return}if(e.key.startsWith('Arrow')){e.preventDefault();return}}}if(e.key.startsWith('Arrow')){e.preventDefault();arrowFocus(e.key)}});
window.addEventListener('blur',()=>{if(state.page==='game'&&!state.modal)showModal('pause')});
render();
